# Optional imaging packages are imported only for explicit actions.
from pathlib import Path

def code_generate(value, kind, path):
    if not value or len(value) > 1000:
        raise ValueError('Enter 1-1000 characters.')
    if kind == 'QR':
        import qrcode
        image = qrcode.make(value)
    else:
        if not value.isascii() or not value.isprintable():
            raise ValueError('Code128 requires printable ASCII text.')
        from barcode import Code128
        from barcode.writer import ImageWriter
        image = Code128(value,writer=ImageWriter()).render()
    image.save(path,format='PNG')

def code_read(path):
    if Path(path).stat().st_size > 20*1024*1024:
        raise ValueError('Image must be at most 20 MB.')
    from PIL import Image
    import zxingcpp
    with Image.open(path) as image:
        if image.width*image.height > 20_000_000:
            raise ValueError('Image dimensions are too large.')
        return [item.text for item in zxingcpp.read_barcodes(image)]

def code_save(app):
    path = filedialog.asksaveasfilename(parent=app.Form1,defaultextension='.png',filetypes=[('PNG','*.png')])
    if not path:
        return
    try:
        code_generate(app.Value.get(),app.Format.get(),path)
        app.Result.delete('1.0','end'); app.Result.insert('1.0','Saved: '+path)
    except Exception as exc:
        messagebox.showerror('Code Studio',str(exc),parent=app.Form1)

def code_open(app):
    path = filedialog.askopenfilename(parent=app.Form1,filetypes=[('Images','*.png *.jpg *.jpeg *.bmp *.gif')])
    if not path:
        return
    try:
        values = code_read(path)
        app.Result.delete('1.0','end'); app.Result.insert('1.0','\n'.join(values) if values else 'No readable code found.')
    except Exception as exc:
        messagebox.showerror('Code Studio',str(exc),parent=app.Form1)
